'use client';

import { suggestPanelContent } from '@/ai/flows/suggest-panel-content';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Lightbulb, Loader2, Sparkles } from 'lucide-react';
import { useState, useTransition } from 'react';

type AISuggestionsProps = {
  panelContent: string;
  panelPurpose: string;
  toolType: string;
};

export function AISuggestions({
  panelContent,
  panelPurpose,
  toolType,
}: AISuggestionsProps) {
  const [isPending, startTransition] = useTransition();
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = () => {
    startTransition(async () => {
      setError(null);
      setSuggestions([]);
      try {
        const result = await suggestPanelContent({
          panelContent,
          panelPurpose,
          toolType,
        });
        setSuggestions(result.suggestions);
      } catch (e) {
        console.error(e);
        setError('Failed to generate suggestions. Please try again.');
      }
    });
  };

  return (
    <Accordion type="single" collapsible className="w-full">
      <AccordionItem value="ai-suggestions">
        <AccordionTrigger className="text-sm hover:no-underline">
          <div className="flex items-center gap-2">
            <Sparkles className="size-4 text-primary" />
            <span>AI Assistance</span>
          </div>
        </AccordionTrigger>
        <AccordionContent className="space-y-4">
          <p className="text-sm text-muted-foreground">
            Generate contextual suggestions based on the panel's content and
            purpose.
          </p>
          <Button onClick={handleGenerate} disabled={isPending} size="sm">
            {isPending ? (
              <Loader2 className="mr-2 animate-spin" />
            ) : (
              <Lightbulb className="mr-2" />
            )}
            Generate Suggestions
          </Button>

          {isPending && (
            <div className="space-y-2">
              <Skeleton className="h-6 w-full" />
              <Skeleton className="h-6 w-5/6" />
              <Skeleton className="h-6 w-2/3" />
            </div>
          )}

          {error && <p className="text-sm text-destructive">{error}</p>}

          {suggestions.length > 0 && (
            <ul className="space-y-2 rounded-md border bg-secondary/50 p-4">
              {suggestions.map((suggestion, index) => (
                <li key={index} className="flex items-start gap-2 text-sm">
                  <Sparkles className="mt-1 size-3 shrink-0 text-primary" />
                  <span>{suggestion}</span>
                </li>
              ))}
            </ul>
          )}
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
}
