'use client';

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { useTransition, type ReactNode } from 'react';
import { deletePanel } from '@/app/actions';
import { useToast } from '@/hooks/use-toast';

type DeletePanelDialogProps = {
  toolId: string;
  tabId: string;
  panelId: string;
  panelTitle: string;
  children: ReactNode;
};

export function DeletePanelDialog({
  toolId,
  tabId,
  panelId,
  panelTitle,
  children,
}: DeletePanelDialogProps) {
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();

  const handleConfirmDelete = () => {
    startTransition(async () => {
      const result = await deletePanel(toolId, tabId, panelId);
      if (result.success) {
        toast({
          title: 'Panel Deleted',
          description: `The panel "${panelTitle}" has been removed.`,
        });
      } else {
        toast({
          variant: 'destructive',
          title: 'Error',
          description: result.error || 'Failed to delete the panel.',
        });
      }
    });
  };

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{children}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>
          <AlertDialogDescription>
            This action cannot be undone. This will permanently delete the
            "{panelTitle}" panel.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction onClick={handleConfirmDelete} disabled={isPending}>
            {isPending ? 'Deleting...' : 'Continue'}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
