'use client';

import { PlaceHolderImages } from '@/lib/placeholder-images';
import type { Panel, Tool } from '@/lib/tools-data';
import { defaultToolIds } from '@/lib/tools-data';
import Image from 'next/image';
import { AISuggestions } from './ai-suggestions';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '../ui/card';
import { ScrollArea } from '../ui/scroll-area';
import { Textarea } from '../ui/textarea';
import { Box, Music } from 'lucide-react';
import { useState, useTransition, useEffect } from 'react';
import { updatePanelContent } from '@/app/actions';
import { useToast } from '@/hooks/use-toast';
import { DeletePanelDialog } from './delete-panel-dialog';

type PanelProps = {
  panel: Panel;
  toolId: Tool['id'];
  tabId: string;
  toolType: Tool['name'];
};

export function ForgePanel({ panel, toolId, tabId, toolType }: PanelProps) {
  const [content, setContent] = useState(panel.content);
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();
  const isDefaultTool = defaultToolIds.includes(toolId);

  // Ensure client state is updated if server data changes
  useEffect(() => {
    setContent(panel.content);
  }, [panel.content]);

  const handleSave = () => {
    // Only save if content has changed and the tool is a custom one
    if (content === panel.content || isDefaultTool) {
      return;
    }
    
    startTransition(async () => {
      const result = await updatePanelContent(toolId, tabId, panel.id, content);
      if (result.success) {
         toast({
          title: 'Content Saved!',
          description: `Your changes to "${panel.title}" have been saved.`,
        });
      } else {
        toast({
          variant: 'destructive',
          title: 'Error',
          description: result.error || 'Failed to save content.',
        });
        // Revert optimistic update on failure
        setContent(panel.content);
      }
    });
  };
  
  const renderContent = () => {
    switch (panel.type) {
      case 'editor':
        return (
          <ScrollArea className="h-64">
            <Textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              onBlur={handleSave}
              disabled={isPending}
              className="h-full min-h-64 w-full resize-none border-0 p-1 focus-visible:ring-0"
              aria-label={panel.title}
              readOnly={isDefaultTool}
            />
          </ScrollArea>
        );
      case 'media':
        const image = PlaceHolderImages.find((img) => img.id === panel.imageId);
        if (!image) {
          return (
            <div className="flex h-64 items-center justify-center rounded-md bg-muted text-muted-foreground">
              Image not found
            </div>
          );
        }
        return (
          <div className="relative h-64 w-full overflow-hidden rounded-md">
            <Image
              src={image.imageUrl}
              alt={image.description}
              fill
              className="object-cover"
              data-ai-hint={image.imageHint}
            />
          </div>
        );
      case 'sound':
        return (
          <div className="flex h-64 flex-col items-center justify-center gap-4 rounded-md bg-muted text-muted-foreground">
            <Music className="size-16" />
            <span className="font-mono text-sm">{panel.content}</span>
          </div>
        );
      case '3d':
        return (
          <div className="flex h-64 flex-col items-center justify-center gap-4 rounded-md bg-muted text-muted-foreground">
            <Box className="size-16" />
            <span className="font-mono text-sm">{panel.content}</span>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <Card className="flex h-full flex-col relative group/panel">
       {!isDefaultTool && (
        <DeletePanelDialog
          toolId={toolId}
          tabId={tabId}
          panelId={panel.id}
          panelTitle={panel.title}
        >
          <button className="absolute top-2 right-2 z-10 hidden h-5 w-5 items-center justify-center rounded-full bg-destructive text-destructive-foreground opacity-80 transition-opacity hover:opacity-100 group-hover/panel:flex">
            &times;
          </button>
        </DeletePanelDialog>
      )}
      <CardHeader>
        <CardTitle>{panel.title}</CardTitle>
        <CardDescription>{panel.purpose}</CardDescription>
      </CardHeader>
      <CardContent className="flex-grow">{renderContent()}</CardContent>
      <CardFooter>
        <AISuggestions
          panelContent={content}
          panelPurpose={panel.purpose}
          toolType={toolType}
        />
      </CardFooter>
    </Card>
  );
}
