'use client';

import { useState, useTransition } from 'react';
import { Plus } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
  } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useToast } from '@/hooks/use-toast';
import { Loader2 } from 'lucide-react';
import { addPanel } from '@/app/actions';
import type { Panel } from '@/lib/tools-data';
import { PlaceHolderImages } from '@/lib/placeholder-images';

const AddPanelSchema = z.object({
  title: z.string().min(1, 'Panel title is required.'),
  type: z.enum(['editor', 'media', 'sound', '3d']),
  purpose: z.string().min(1, 'Panel purpose is required.'),
  imageId: z.string().optional(),
});

type AddPanelFormValues = z.infer<typeof AddPanelSchema>;

type AddPanelDialogProps = {
  toolId: string;
  tabId: string;
};

export function AddPanelDialog({ toolId, tabId }: AddPanelDialogProps) {
  const [open, setOpen] = useState(false);
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();

  const form = useForm<AddPanelFormValues>({
    resolver: zodResolver(AddPanelSchema),
    defaultValues: {
      title: '',
      type: 'editor',
      purpose: '',
      imageId: undefined,
    },
  });

  const panelType = form.watch('type');

  const onSubmit = async (values: AddPanelFormValues) => {
    if (values.type === 'media' && !values.imageId) {
        form.setError('imageId', { message: 'Please select an image for the media panel.' });
        return;
    }

    startTransition(async () => {
      try {
        const panelData: Omit<Panel, 'id' | 'content'> = {
            title: values.title,
            type: values.type,
            purpose: values.purpose,
            imageId: values.type === 'media' ? values.imageId : undefined,
        }
        const result = await addPanel(toolId, tabId, panelData);

        if (result.success) {
          toast({
            title: 'Panel Created!',
            description: `The panel "${values.title}" has been added.`,
          });
          setOpen(false);
          form.reset();
        } else {
          throw new Error(result.error);
        }
      } catch (error) {
        console.error('Failed to create new panel:', error);
        toast({
          variant: 'destructive',
          title: 'Error',
          description:
            error instanceof Error
              ? error.message
              : 'Failed to create new panel. Please try again.',
        });
      }
    });
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm">
          <Plus className="mr-2 h-4 w-4" />
          Add Panel
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Add a New Panel</DialogTitle>
          <DialogDescription>
            Configure the details for your new panel.
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="title"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Panel Title</FormLabel>
                  <FormControl>
                    <Input placeholder="e.g., 'Character Backstory'" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
             <FormField
              control={form.control}
              name="purpose"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Panel Purpose</FormLabel>
                  <FormControl>
                    <Input placeholder="e.g., 'To flesh out the main character'" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
                control={form.control}
                name="type"
                render={({ field }) => (
                    <FormItem>
                        <FormLabel>Panel Type</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                            <SelectTrigger>
                                <SelectValue placeholder="Select a panel type" />
                            </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                                <SelectItem value="editor">Editor</SelectItem>
                                <SelectItem value="media">Media</SelectItem>
                                <SelectItem value="sound">Sound</SelectItem>
                                <SelectItem value="3d">3D</SelectItem>
                            </SelectContent>
                        </Select>
                        <FormMessage />
                    </FormItem>
                )}
            />
             {panelType === 'media' && (
              <FormField
                control={form.control}
                name="imageId"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Placeholder Image</FormLabel>
                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                      <FormControl>
                        <SelectTrigger>
                          <SelectValue placeholder="Select an image" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {PlaceHolderImages.map((image) => (
                          <SelectItem key={image.id} value={image.id}>
                            {image.description}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            )}
            <DialogFooter>
                <DialogClose asChild>
                    <Button variant="ghost">Cancel</Button>
                </DialogClose>
                <Button type="submit" disabled={isPending}>
                {isPending && <Loader2 className="mr-2 animate-spin" />}
                Add Panel
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
